package li.cil.oc.server.component;

import li.cil.oc.Settings;
import li.cil.oc.api.internal.Database;
import li.cil.oc.api.machine.*;
import li.cil.oc.api.network.*;
import li.cil.oc.api.prefab.ItemStackArrayValue;
import li.cil.oc.util.InventoryUtils;
import net.minecraft.core.Direction;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.world.item.ItemStack;
import net.neoforged.neoforge.items.IItemHandler;
import java.util.*;
import java.util.function.Function;

/** Original world inventory analytics. Agent-specific control is exposed only by its agent subtype. */
public class UpgradeInventoryController extends UpgradeBase {
    public UpgradeInventoryController(EnvironmentHost host){super(host,"inventory_controller","Inventory controller","Item Cataloguer R1",false);}
    @Override protected Direction side(Arguments args,int index){int value=args.checkInteger(index);if(value<0||value>5||host instanceof li.cil.oc.api.internal.Robot&&value!=0&&value!=1&&value!=3)throw new IllegalArgumentException("invalid side");Direction side=Direction.from3DDataValue(value);return host instanceof li.cil.oc.api.internal.Robot robot?robot.toGlobal(side):side;}
    protected Object[] inventory(Arguments args,Function<IItemHandler,Object[]> action){Direction direction=side(args,0);var source=InventoryUtils.inventorySourceAt(host.world(),position().relative(direction),direction.getOpposite());return source.isPresent()&&mayInteract(source.get())?action.apply(source.get().inventory()):new Object[]{null,"no inventory"};}
    protected Database database(String address){Node target=node().network()==null?null:node().network().node(address);if(target==null||!target.canBeReachedFrom(node()))throw new IllegalArgumentException("no such component");if(!(target.host() instanceof Database database))throw new IllegalArgumentException("not a database");return database;}
    @Callback(doc="function(side:number):number -- Get the number of inventory slots.") public Object[] getInventorySize(Context context,Arguments args){return inventory(args,handler->new Object[]{handler.getSlots()});}
    @Callback(doc="function(side:number,slot:number):number -- Get the stack size in a slot.") public Object[] getSlotStackSize(Context context,Arguments args){return inventory(args,handler->new Object[]{handler.getStackInSlot(slot(args,1,handler.getSlots())).getCount()});}
    @Callback(doc="function(side:number,slot:number):number -- Get the maximum stack size in a slot.") public Object[] getSlotMaxStackSize(Context context,Arguments args){return inventory(args,handler->{ItemStack stack=handler.getStackInSlot(slot(args,1,handler.getSlots()));return new Object[]{stack.isEmpty()?0:stack.getMaxStackSize()};});}
    @Callback(doc="function(side:number,slotA:number,slotB:number[,checkNBT:boolean]):boolean -- Compare two item stacks.") public Object[] compareStacks(Context context,Arguments args){return inventory(args,handler->{ItemStack a=handler.getStackInSlot(slot(args,1,handler.getSlots())),b=handler.getStackInSlot(slot(args,2,handler.getSlots()));return new Object[]{a==b||InventoryUtils.haveSameItemType(a,b,args.optBoolean(3,false))};});}
    @Callback(doc="function(side:number,slot:number,dbAddress:string,dbSlot:number[,checkNBT:boolean]):boolean -- Compare a stack to a database entry.") public Object[] compareStackToDatabase(Context context,Arguments args){return inventory(args,handler->{Database database=database(args.checkString(2));return new Object[]{InventoryUtils.haveSameItemType(handler.getStackInSlot(slot(args,1,handler.getSlots())),Objects.requireNonNullElse(database.getStackInSlot(slot(args,3,database.size())),ItemStack.EMPTY),args.optBoolean(4,false))};});}
    @Callback(doc="function(side:number,slotA:number,slotB:number):boolean -- Check whether two stacks share an item tag.") public Object[] areStacksEquivalent(Context context,Arguments args){return inventory(args,handler->{ItemStack a=handler.getStackInSlot(slot(args,1,handler.getSlots())),b=handler.getStackInSlot(slot(args,2,handler.getSlots()));return new Object[]{a==b||!a.isEmpty()&&!b.isEmpty()&&a.getTags().anyMatch(b::is)};});}
    @Callback(doc="function(side:number,slot:number):table -- Inspect a stack.") public Object[] getStackInSlot(Context context,Arguments args){return Settings.get().allowItemStackInspection?inventory(args,handler->new Object[]{handler.getStackInSlot(slot(args,1,handler.getSlots())).copy()}):new Object[]{null,"not enabled in config"};}
    @Callback(doc="function(side:number):userdata -- Inspect all stacks.") public Object[] getAllStacks(Context context,Arguments args){return Settings.get().allowItemStackInspection?inventory(args,handler->{ItemStack[] stacks=new ItemStack[handler.getSlots()];for(int i=0;i<stacks.length;i++)stacks[i]=handler.getStackInSlot(i).copy();return new Object[]{new ItemStackArrayValue(stacks,host.world().registryAccess())};}):new Object[]{null,"not enabled in config"};}
    @Callback(doc="function(side:number):string -- Get the inventory registry name.") public Object[] getInventoryName(Context context,Arguments args){if(!Settings.get().allowItemStackInspection)return new Object[]{null,"not enabled in config"};Direction side=side(args,0);var source=InventoryUtils.inventorySourceAt(host.world(),position().relative(side),side.getOpposite());if(source.isEmpty()||!mayInteract(source.get()))return new Object[]{null,"no inventory"};return new Object[]{source.get() instanceof InventoryUtils.BlockInventorySource block?BuiltInRegistries.BLOCK.getKey(host.world().getBlockState(block.position()).getBlock()).toString():BuiltInRegistries.ENTITY_TYPE.getKey(((InventoryUtils.EntityInventorySource)source.get()).entity().getType()).toString()};}
    @Callback(doc="function(side:number,slot:number,dbAddress:string,dbSlot:number):boolean -- Store a stack in a database.") public Object[] store(Context context,Arguments args){return inventory(args,handler->{Database database=database(args.checkString(2));int to=slot(args,3,database.size());ItemStack old=database.getStackInSlot(to);database.setStackInSlot(to,handler.getStackInSlot(slot(args,1,handler.getSlots())).copy());return new Object[]{old!=null&&!old.isEmpty()};});}

    public static class Agent extends UpgradeInventoryController {
        protected final li.cil.oc.api.internal.Agent agent;
        public Agent(EnvironmentHost host){super(host);agent=(li.cil.oc.api.internal.Agent)host;}
        protected int internalSlot(Arguments args,int index){return defined(args,index)?slot(args,index,agent.mainInventory().getContainerSize()):agent.selectedSlot();}
        protected List<Integer> insertionSlots(){List<Integer> result=new ArrayList<>();if(agent.selectedSlot()>=0)result.add(agent.selectedSlot());for(int i=0;i<agent.mainInventory().getContainerSize();i++)if(i!=agent.selectedSlot())result.add(i);return result;}
        @Callback public Object[] getStackInInternalSlot(Context context,Arguments args){return Settings.get().allowItemStackInspection?new Object[]{agent.mainInventory().getItem(internalSlot(args,0)).copy()}:new Object[]{null,"not enabled in config"};}
        @Callback public Object[] isEquivalentTo(Context context,Arguments args){ItemStack a=agent.mainInventory().getItem(agent.selectedSlot()),b=agent.mainInventory().getItem(slot(args,0,agent.mainInventory().getContainerSize()));return new Object[]{a.isEmpty()&&b.isEmpty()||!a.isEmpty()&&!b.isEmpty()&&a.getTags().anyMatch(b::is)};}
        @Callback public Object[] storeInternal(Context context,Arguments args){ItemStack stack=agent.mainInventory().getItem(slot(args,0,agent.mainInventory().getContainerSize()));Database target=database(args.checkString(1));int index=slot(args,2,target.size());ItemStack old=target.getStackInSlot(index);target.setStackInSlot(index,stack);return new Object[]{old!=null&&!old.isEmpty()};}
        @Callback public Object[] compareToDatabase(Context context,Arguments args){ItemStack stack=agent.mainInventory().getItem(slot(args,0,agent.mainInventory().getContainerSize()));Database target=database(args.checkString(1));return new Object[]{InventoryUtils.haveSameItemType(stack,Objects.requireNonNullElse(target.getStackInSlot(slot(args,2,target.size())),ItemStack.EMPTY),args.optBoolean(3,false))};}
        private Object[] adjacent(Arguments args,Function<IItemHandler,Object[]> action){Direction facing=side(args,0),access=defined(args,3)?Direction.from3DDataValue(sideValue(args,3)):facing.getOpposite();var source=InventoryUtils.inventorySourceAt(host.world(),position().relative(facing),access);return source.isPresent()&&mayInteract(source.get())?action.apply(source.get().inventory()):new Object[]{null,"no inventory"};}
        private int sideValue(Arguments args,int index){int value=args.checkInteger(index);if(value<0||value>5)throw new IllegalArgumentException("invalid side");return value;}
        @Callback public Object[] dropIntoSlot(Context context,Arguments args){return adjacent(args,target->{ItemStack stack=agent.mainInventory().getItem(agent.selectedSlot());boolean moved=InventoryUtils.insertIntoInventorySlot(stack,target,slot(args,1,target.getSlots()),Math.max(0,Math.min(64,args.optInteger(2,64))),false);if(moved){agent.mainInventory().setChanged();changed();context.pause(Settings.get().config.getDouble("robot.delays.drop"));}return moved?new Object[]{true}:new Object[]{false,"inventory full/invalid slot"};});}
        @Callback public Object[] suckFromSlot(Context context,Arguments args){return adjacent(args,source->{int moved=InventoryUtils.extractFromInventorySlot((stack,simulate)->InventoryUtils.insertIntoInventory(stack,InventoryUtils.asItemHandler(agent.mainInventory()),stack.getCount(),simulate,insertionSlots()),source,slot(args,1,source.getSlots()),Math.max(0,Math.min(64,args.optInteger(2,64))));if(moved>0){changed();context.pause(Settings.get().config.getDouble("robot.delays.suck"));}return moved>0?new Object[]{moved}:new Object[]{false};});}
        private Object[] itemInventory(Arguments args,Function<IItemHandler,Object[]> action){IItemHandler handler=li.cil.oc.api.Driver.itemHandlerFor(agent.mainInventory().getItem(slot(args,0,agent.mainInventory().getContainerSize())),fakePlayer());return handler==null?new Object[]{0,"no item inventory"}:action.apply(handler);}
        @Callback public Object[] getItemInventorySize(Context context,Arguments args){return itemInventory(args,handler->new Object[]{handler.getSlots()});}
        @Callback public Object[] dropIntoItemInventory(Context context,Arguments args){if(slot(args,0,agent.mainInventory().getContainerSize())==agent.selectedSlot())return new Object[]{0};return itemInventory(args,handler->{int moved=InventoryUtils.transferBetweenInventoriesSlots(InventoryUtils.asItemHandler(agent.mainInventory()),agent.selectedSlot(),handler,slot(args,1,handler.getSlots()),Math.max(0,Math.min(64,args.optInteger(2,64))));changed();return new Object[]{moved};});}
        @Callback public Object[] suckFromItemInventory(Context context,Arguments args){if(slot(args,0,agent.mainInventory().getContainerSize())==agent.selectedSlot())return new Object[]{0};return itemInventory(args,handler->{int moved=InventoryUtils.extractFromInventorySlot((stack,simulate)->InventoryUtils.insertIntoInventory(stack,InventoryUtils.asItemHandler(agent.mainInventory()),stack.getCount(),simulate,insertionSlots()),handler,slot(args,1,handler.getSlots()),Math.max(0,Math.min(64,args.optInteger(2,64))));changed();return new Object[]{moved};});}
    }
    public static final class Robot extends Agent {
        public Robot(EnvironmentHost host){super(host);}
        @Callback public Object[] equip(Context context,Arguments args){if(agent.mainInventory().getContainerSize()==0)return new Object[]{false};ItemStack equipped=agent.equipmentInventory().getItem(0),selected=agent.mainInventory().getItem(agent.selectedSlot());agent.equipmentInventory().setItem(0,selected);agent.mainInventory().setItem(agent.selectedSlot(),equipped);changed();return new Object[]{true};}
    }
}
